import networkx as nx
from collections import defaultdict
import random
import math

class BroadCastTopology:
    def __init__(self, src: str, dsts: list, num_partitions: int):
        self.src = src
        self.dsts = dsts
        self.num_partitions = int(num_partitions)
        self.paths = {dst: {str(i): None for i in range(self.num_partitions)} for dst in dsts}

    def append_dst_partition_path(self, dst: str, partition: int, path: list):
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

    def set_dst_partition_paths(self, dst: str, partition: int, paths: list):
        partition = str(partition)
        self.paths[dst][partition] = paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions


def search_algorithm(src, dsts, G, num_partitions):
    bc_topology = BroadCastTopology(src, dsts, num_partitions)

    def path_to_edges(path):
        edges = []
        for i in range(len(path) - 1):
            u, v = path[i], path[i+1]
            edata = dict(G[u][v])
            edges.append([u, v, edata])
        return edges

    def path_cost(path):
        c = 0.0
        for i in range(len(path) - 1):
            c += G[path[i]][path[i+1]].get("cost", 0.0)
        return c

    K = 15
    dst_paths = {}
    for dst in dsts:
        candidates = []
        try:
            gen = nx.shortest_simple_paths(G, src, dst, weight="cost")
            for i, p in enumerate(gen):
                if i >= K:
                    break
                candidates.append(p)
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            pass
        # Also try fewest hops
        try:
            sp = nx.shortest_path(G, src, dst)
            if sp not in candidates:
                candidates.append(sp)
        except:
            pass
        # Also try by throughput (max min throughput path)
        try:
            inv_tp_G = nx.DiGraph()
            for u, v, d in G.edges(data=True):
                tp = d.get("throughput", 1.0)
                inv_tp_G.add_edge(u, v, weight=1.0/(tp + 1e-9), **d)
            tp_path = nx.shortest_path(inv_tp_G, src, dst, weight="weight")
            if tp_path not in candidates:
                candidates.append(tp_path)
        except:
            pass
        dst_paths[dst] = candidates

    # Simple strategy: all partitions use cheapest path
    for dst in dsts:
        candidates = dst_paths.get(dst, [])
        if not candidates:
            continue
        # Use cheapest path for all partitions
        best_path = min(candidates, key=path_cost)
        edges = path_to_edges(best_path)
        for p in range(num_partitions):
            bc_topology.set_dst_partition_paths(dst, p, edges)

    return bc_topology
'''
